from AlgorithmImports import *
from datetime import datetime, time, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute, DataNormalizationMode.Raw).Symbol
        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self.option_symbol].SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(timedelta(0), timedelta(365))
        )

        self.close_window = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.expiration_block_date = None

    def OnData(self, slice):
        if self.Portfolio[self.spy].Quantity != 0:
            if not self._has_open_order(self.spy):
                self.Debug(
                    f"{self.Time}: Unexpected SPY position from exercise/assignment; liquidating."
                )
                self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.expiration_block_date = self.Time.date()
            if not self._has_open_order(self.held_contract):
                self.Debug(
                    f"{self.Time}: Expiration processing for {self.held_contract}; liquidating."
                )
                self._submit_exit("expiration")
            return

        if (
            self.Time.hour == 15
            and self.Time.minute == 45
            and self.Time.date() == self._previous_trading_day(expiry_date)
        ):
            if not self._has_open_order(self.held_contract):
                self.Debug(
                    f"{self.Time}: Pre-expiration time stop for {self.held_contract}; liquidating."
                )
                self._submit_exit("time stop")
            return

        if self.entry_fill_price is None or self._has_open_order(self.held_contract):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (candidate for candidate in chain if candidate.Symbol == self.held_contract),
            None,
        )
        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.Debug(
                f"{self.Time}: Profit target reached for {self.held_contract}; liquidating."
            )
            self._submit_exit("profit target")

    def OnFiveMinuteBar(self, sender, bar):
        self.close_window.Add(float(bar.Close))

        if not self.close_window.IsReady:
            return

        closes = [self.close_window[i] for i in range(self.close_window.Count)]
        fast = sum(closes[:5]) / 5.0
        slow = sum(closes[:20]) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        end_time = bar.EndTime
        if not (
            (end_time.hour == 9 and end_time.minute >= 45)
            or 10 <= end_time.hour <= 13
            or (end_time.hour == 14 and end_time.minute <= 30)
        ):
            return

        if self.expiration_block_date == self.Time.date():
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            return

        if self.entry_order_id is not None and self._has_open_order_id(self.entry_order_id):
            return

        slice = self.CurrentSlice
        chain = slice.OptionChains.get(self.option_symbol) if slice is not None else None
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped; no SPY option chain in Slice.")
            return

        current_date = self.Time.date()
        eligible_expiries = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if (contract.Expiry.date() - current_date).days >= 7
            }
        )
        if not eligible_expiries:
            self.Debug(f"{self.Time}: Entry skipped; no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        spy_price = bar.Close
        qualifying_calls = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= spy_price * 1.01
        ]

        if not qualifying_calls:
            self.Debug(
                f"{self.Time}: Entry skipped; no qualifying call at expiration {selected_expiry}."
            )
            return

        selected = min(qualifying_calls, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_contract = selected.Symbol
        self.entry_fill_price = None
        self.Debug(f"{self.Time}: Entering 1 {selected.Symbol} with market order.")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_fill_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: Entry filled for {self.held_contract} at {order_event.FillPrice}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"{self.Time}: Entry order {order_event.OrderId} did not fill.")
                self.entry_order_id = None
                self.held_contract = None
                self.entry_fill_price = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: Exit filled for {self.held_contract}.")
                self.exit_order_id = None
                self.entry_order_id = None
                self.held_contract = None
                self.entry_fill_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

    def _submit_exit(self, reason):
        if self.held_contract is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id, f"Canceling before {reason} exit")

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity > 0:
            ticket = self.MarketOrder(self.held_contract, -quantity)
            self.exit_order_id = ticket.OrderId

    def _has_open_order(self, symbol):
        return len(self.Transactions.GetOpenOrders(symbol)) > 0

    def _has_open_order_id(self, order_id):
        if order_id is None:
            return False
        order = self.Transactions.GetOrderById(order_id)
        return order is not None and order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(datetime.combine(candidate, time.min)):
            candidate -= timedelta(days=1)

        return candidate

